let lang=localStorage.getItem("fardar-lang")||"fa";
if(!translations[lang])lang="fa";
const dirs={fa:"rtl",ar:"rtl",en:"ltr",zh:"ltr"};
const locale={fa:"fa",ar:"ar",en:"en",zh:"zh-CN"};
function renderLanguage(){
  const primary=translations[lang],fallback=translations.en;
  document.documentElement.lang=locale[lang];
  document.documentElement.dir=dirs[lang];
  document.querySelectorAll("[data-t]").forEach(el=>{const key=el.dataset.t;const value=primary[key]??fallback[key]??translations.fa[key];if(value!==undefined)el.innerHTML=value});
  document.querySelectorAll("[data-lang]").forEach(b=>b.classList.toggle("active",b.dataset.lang===lang));
}
document.querySelectorAll("[data-lang]").forEach(btn=>btn.addEventListener("click",()=>{lang=btn.dataset.lang;localStorage.setItem("fardar-lang",lang);renderLanguage()}));
const menu=document.querySelector(".menu-button");
menu?.addEventListener("click",e=>{const nav=document.querySelector(".mobile-nav");const open=nav.classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",String(open))});
document.querySelectorAll(".mobile-nav a").forEach(a=>a.addEventListener("click",()=>{document.querySelector(".mobile-nav")?.classList.remove("open");menu?.setAttribute("aria-expanded","false")}));
if("IntersectionObserver" in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll(".reveal").forEach(el=>observer.observe(el))}else{document.querySelectorAll(".reveal").forEach(el=>el.classList.add("visible"))}
renderLanguage();
